FROM (
    SELECT match_id, inning, SUM(runs_scored + extra_runs) AS total_score
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches WHERE city = 'Ahmedabad'
    )
    AND inning = 1
    GROUP BY match_id, inning
) AS inning_totals;

